HISTORIQUES = (
    (1416, 'Produit scalaire, colinéarité et orthogonalité de vecteurs', 1, 'Dans un repère orthonormé, on donne les vecteurs $\\vec{u}(-5 ; 4)$ et $\\vec{v}(6 ; k)$. Déterminer la valeur de $k$ pour laquelle $\\vec{u}$ et $\\vec{v}$ sont orthogonaux.', '$k = \\dfrac{15}{2}$', 'Deux vecteurs sont orthogonaux si, et seulement si, $\\vec{u}\\cdot\\vec{v}=0$.', ('Étape 1 : Deux vecteurs sont orthogonaux si, et seulement si, leur produit scalaire est nul.', 'Étape 2 : $\\vec{u}\\cdot\\vec{v} = -5\\times6 + 4\\times k = 0$.', 'Étape 3 : $-30 + 4k = 0 \\iff k = \\dfrac{15}{2}$.')),
    (1418, 'Produit scalaire, colinéarité et orthogonalité de vecteurs', 1, 'Dans un repère orthonormé, on donne les vecteurs $\\vec{u}(-2 ; -3)$ et $\\vec{v}(2 ; k)$. Déterminer la valeur de $k$ pour laquelle $\\vec{u}$ et $\\vec{v}$ sont colinéaires.', '$k = 3$', 'Utiliser le critère de colinéarité $x_uy_v-x_vy_u=0$ (déterminant nul).', ('Étape 1 : Deux vecteurs $\\vec{u}(x_u;y_u)$ et $\\vec{v}(x_v;y_v)$ sont colinéaires si, et seulement si, $x_uy_v - x_vy_u = 0$.', 'Étape 2 : $-2\\times k - 2\\times-3 = 0 \\iff -2k = -6 \\iff k = 3$.')),
    (1420, 'Produit scalaire, colinéarité et orthogonalité de vecteurs', 1, 'Dans un repère orthonormé, on donne les vecteurs $\\vec{u}(-1 ; 4)$ et $\\vec{v}(-6 ; -5)$. Calculer le produit scalaire $\\vec{u} \\cdot \\vec{v}$.', '$\\vec{u}\\cdot\\vec{v} = -14$', 'Utiliser la formule $\\vec{u}\\cdot\\vec{v} = x_ux_v+y_uy_v$.', ('Étape 1 : On utilise $\\vec{u}\\cdot\\vec{v} = x_ux_v + y_uy_v$.', 'Étape 2 : $\\vec{u}\\cdot\\vec{v} = -1\\times-6 + 4\\times-5 = 6 + -20 = -14$.')),
    (1475, 'Autres définitions et propriétés', 1, 'Deux vecteurs $\\vec{u}$ et $\\vec{v}$ vérifient $\\|\\vec{u}\\| = 9$, $\\|\\vec{v}\\| = 5$ et $\\left(\\vec{u} ; \\vec{v}\\right) = \\dfrac{\\pi}{6}$ (angle géométrique). Calculer $\\vec{u}\\cdot\\vec{v}$.', '$\\vec{u}\\cdot\\vec{v} = \\left(\\dfrac{45}{2}\\right)\\sqrt{3}$', 'Utiliser $\\vec{u}\\cdot\\vec{v} = \\|\\vec{u}\\|\\,\\|\\vec{v}\\|\\cos(\\vec{u},\\vec{v})$.', ('Étape 1 : On utilise la formule $\\vec{u}\\cdot\\vec{v} = \\|\\vec{u}\\| \\times \\|\\vec{v}\\| \\times \\cos(\\vec{u},\\vec{v})$.', 'Étape 2 : $\\vec{u}\\cdot\\vec{v} = 9\\times5\\times\\dfrac{\\sqrt{3}}{2} = \\left(\\dfrac{45}{2}\\right)\\sqrt{3}$.')),
    (1476, 'Autres définitions et propriétés', 1, 'Deux vecteurs $\\vec{u}$ et $\\vec{v}$ vérifient $\\|\\vec{u}\\| = 6$, $\\|\\vec{v}\\| = 10$ et $\\left(\\vec{u} ; \\vec{v}\\right) = 0$ (angle géométrique). Calculer $\\vec{u}\\cdot\\vec{v}$.', '$\\vec{u}\\cdot\\vec{v} = 60$', 'Utiliser $\\vec{u}\\cdot\\vec{v} = \\|\\vec{u}\\|\\,\\|\\vec{v}\\|\\cos(\\vec{u},\\vec{v})$.', ('Étape 1 : On utilise la formule $\\vec{u}\\cdot\\vec{v} = \\|\\vec{u}\\| \\times \\|\\vec{v}\\| \\times \\cos(\\vec{u},\\vec{v})$.', 'Étape 2 : $\\vec{u}\\cdot\\vec{v} = 6\\times10\\times1 = 60$.')),
    (1479, 'Autres définitions et propriétés', 1, 'On donne $\\vec{u}\\cdot\\vec{v} = -6$, $\\|\\vec{u}\\|^2 = 3$ et $\\|\\vec{v}\\|^2 = 10$. Calculer $(\\vec{u}+\\vec{v})\\cdot(\\vec{u}+\\vec{v})$.', '$(\\vec{u}+\\vec{v})\\cdot(\\vec{u}+\\vec{v}) = 1$', 'Développer comme une identité remarquable, en utilisant $\\vec{u}\\cdot\\vec{u} = \\|\\vec{u}\\|^2$.', ('Étape 1 : On développe : $(\\vec{u}+\\vec{v})\\cdot(\\vec{u}+\\vec{v}) = \\|\\vec{u}\\|^2 + 2\\,\\vec{u}\\cdot\\vec{v} + \\|\\vec{v}\\|^2$.', 'Étape 2 : $= 3 + 2\\times-6 + 10 = 1$.')),
    (1480, 'Autres définitions et propriétés', 1, 'On donne $\\|\\vec{u}\\|^2 = 5$ et $\\|\\vec{v}\\|^2 = 10$. Calculer $(\\vec{u}+\\vec{v})\\cdot(\\vec{u}-\\vec{v})$.', '$(\\vec{u}+\\vec{v})\\cdot(\\vec{u}-\\vec{v}) = -5$', 'Développer comme une identité remarquable, en utilisant $\\vec{u}\\cdot\\vec{u} = \\|\\vec{u}\\|^2$.', ('Étape 1 : On développe : $(\\vec{u}+\\vec{v})\\cdot(\\vec{u}-\\vec{v}) = \\|\\vec{u}\\|^2 - \\|\\vec{v}\\|^2$.', 'Étape 2 : $= 5 - 10 = -5$.')),
    (1534, "Étude d'un ensemble de points", 1, "On donne le point $A(5 ; -3)$ et le vecteur $\\vec{u}(-4 ; 5)$. Déterminer, en la caractérisant géométriquement, l'ensemble des points $M(x;y)$ du plan tels que $\\vec{AM} \\cdot \\vec{u} = 0$.", "La droite passant par $A$ de vecteur normal $\\vec{u}$, d'équation $-4x + 5y +35 = 0$", 'Cette relation caractérise la droite passant par $A$ et de vecteur normal $\\vec{u}$.', ('Étape 1 : $\\vec{AM}\\cdot\\vec{u}=0$ signifie que $\\vec{AM}$ est orthogonal à $\\vec{u}$.', "Étape 2 : L'ensemble cherché est donc la droite passant par $A$ et de vecteur normal $\\vec{u}$.", 'Étape 3 : En coordonnées, $\\vec{AM}\\cdot\\vec{u} = -4(x-(5)) + 5(y-(-3)) = 0$, soit $-4x + 5y +35 = 0$.')),
    (1535, "Étude d'un ensemble de points", 1, "On donne les points $A(4 ; 2)$ et $B(-5 ; 2)$. Déterminer l'ensemble des points $M$ du plan tels que $\\vec{MA} \\cdot \\vec{MB} = 0$.", 'Le cercle de diamètre $[AB]$, de centre $\\Omega\\left(-\\dfrac{1}{2} ; 2\\right)$ et de rayon $\\sqrt{\\dfrac{81}{4}}$', '$\\vec{MA}\\cdot\\vec{MB}=0 \\iff MA \\perp MB \\iff M$ appartient au cercle de diamètre $[AB]$.', ('Étape 1 : La relation $\\vec{MA}\\cdot\\vec{MB}=0$ signifie que les vecteurs $\\vec{MA}$ et $\\vec{MB}$ sont orthogonaux, ce qui caractérise le cercle de diamètre $[AB]$.', 'Étape 2 : Le centre de ce cercle est le milieu de $[AB]$, soit $\\Omega\\left(-\\dfrac{1}{2} ; 2\\right)$.', 'Étape 3 : Le rayon est $\\dfrac{AB}{2}$, avec $AB^2 = (-5-(4))^2+(2-(2))^2 = 81$.')),
    (2092, 'Autres définitions et propriétés', 2, 'Deux vecteurs $\\vec{u}$ et $\\vec{v}$ vérifient $\\|\\vec{u}\\| = 7$, $\\|\\vec{v}\\| = 3$ et $\\left(\\vec{u} ; \\vec{v}\\right) = \\dfrac{2\\pi}{3}$ (angle géométrique). Calculer $\\vec{u}\\cdot\\vec{v}$.', '$\\vec{u}\\cdot\\vec{v} = -\\left(\\dfrac{21}{2}\\right)$', 'Utiliser $\\vec{u}\\cdot\\vec{v} = \\|\\vec{u}\\|\\,\\|\\vec{v}\\|\\cos(\\vec{u},\\vec{v})$ ; un angle obtus donne un cosinus négatif.', ('Étape 1 : On utilise la formule $\\vec{u}\\cdot\\vec{v} = \\|\\vec{u}\\| \\times \\|\\vec{v}\\| \\times \\cos(\\vec{u},\\vec{v})$.', 'Étape 2 : $\\cos\\left(\\dfrac{2\\pi}{3}\\right) = -\\dfrac{1}{2}$, donc $\\vec{u}\\cdot\\vec{v} = 7\\times3\\times\\left(-\\dfrac{1}{2}\\right) = -\\left(\\dfrac{21}{2}\\right)$.')),
    (2093, 'Autres définitions et propriétés', 2, 'Deux vecteurs $\\vec{u}$ et $\\vec{v}$ vérifient $\\|\\vec{u}\\| = 4$, $\\|\\vec{v}\\| = 6$ et $\\left(\\vec{u} ; \\vec{v}\\right) = \\dfrac{3\\pi}{4}$ (angle géométrique). Calculer $\\vec{u}\\cdot\\vec{v}$.', '$\\vec{u}\\cdot\\vec{v} = -12\\sqrt{2}$', 'Utiliser $\\vec{u}\\cdot\\vec{v} = \\|\\vec{u}\\|\\,\\|\\vec{v}\\|\\cos(\\vec{u},\\vec{v})$ ; un angle obtus donne un cosinus négatif.', ('Étape 1 : On utilise la formule $\\vec{u}\\cdot\\vec{v} = \\|\\vec{u}\\| \\times \\|\\vec{v}\\| \\times \\cos(\\vec{u},\\vec{v})$.', 'Étape 2 : $\\cos\\left(\\dfrac{3\\pi}{4}\\right) = -\\dfrac{\\sqrt{2}}{2}$, donc $\\vec{u}\\cdot\\vec{v} = 4\\times6\\times\\left(-\\dfrac{\\sqrt{2}}{2}\\right) = -12\\sqrt{2}$.')),
    (2094, 'Autres définitions et propriétés', 3, 'Deux vecteurs $\\vec{u}$ et $\\vec{v}$ vérifient $\\|\\vec{u}\\| = 5$, $\\|\\vec{v}\\| = 9$ et $\\left(\\vec{u} ; \\vec{v}\\right) = \\dfrac{5\\pi}{6}$ (angle géométrique). Calculer $\\vec{u}\\cdot\\vec{v}$.', '$\\vec{u}\\cdot\\vec{v} = -\\left(\\dfrac{45}{2}\\right)\\sqrt{3}$', 'Utiliser $\\vec{u}\\cdot\\vec{v} = \\|\\vec{u}\\|\\,\\|\\vec{v}\\|\\cos(\\vec{u},\\vec{v})$ ; un angle obtus donne un cosinus négatif.', ('Étape 1 : On utilise la formule $\\vec{u}\\cdot\\vec{v} = \\|\\vec{u}\\| \\times \\|\\vec{v}\\| \\times \\cos(\\vec{u},\\vec{v})$.', 'Étape 2 : $\\cos\\left(\\dfrac{5\\pi}{6}\\right) = -\\dfrac{\\sqrt{3}}{2}$, donc $\\vec{u}\\cdot\\vec{v} = 5\\times9\\times\\left(-\\dfrac{\\sqrt{3}}{2}\\right) = -\\left(\\dfrac{45}{2}\\right)\\sqrt{3}$.')),
    (2095, 'Autres définitions et propriétés', 1, 'Deux vecteurs $\\vec{u}$ et $\\vec{v}$ vérifient $\\|\\vec{u}\\| = 8$, $\\|\\vec{v}\\| = 2$ et $\\left(\\vec{u} ; \\vec{v}\\right) = \\dfrac{2\\pi}{3}$ (angle géométrique). Calculer $\\vec{u}\\cdot\\vec{v}$.', '$\\vec{u}\\cdot\\vec{v} = -8$', 'Utiliser $\\vec{u}\\cdot\\vec{v} = \\|\\vec{u}\\|\\,\\|\\vec{v}\\|\\cos(\\vec{u},\\vec{v})$ ; un angle obtus donne un cosinus négatif.', ('Étape 1 : On utilise la formule $\\vec{u}\\cdot\\vec{v} = \\|\\vec{u}\\| \\times \\|\\vec{v}\\| \\times \\cos(\\vec{u},\\vec{v})$.', 'Étape 2 : $\\cos\\left(\\dfrac{2\\pi}{3}\\right) = -\\dfrac{1}{2}$, donc $\\vec{u}\\cdot\\vec{v} = 8\\times2\\times\\left(-\\dfrac{1}{2}\\right) = -8$.')),
    (2096, 'Autres définitions et propriétés', 1, 'On donne $\\vec{u}\\cdot\\vec{v} = 6$, $\\|\\vec{u}\\|^2 = 7$ et $\\|\\vec{v}\\|^2 = 8$. Calculer $(\\vec{u}+\\vec{v})\\cdot(\\vec{u}+\\vec{v})$.', '$(\\vec{u}+\\vec{v})\\cdot(\\vec{u}+\\vec{v}) = 27$', 'Développer comme une identité remarquable, en utilisant $\\vec{u}\\cdot\\vec{u} = \\|\\vec{u}\\|^2$.', ('Étape 1 : On développe : $(\\vec{u}+\\vec{v})\\cdot(\\vec{u}+\\vec{v}) = \\|\\vec{u}\\|^2 + 2\\,\\vec{u}\\cdot\\vec{v} + \\|\\vec{v}\\|^2$.', 'Étape 2 : $= 7 + 2\\times6 + 8 = 27$.')),
    (2097, 'Autres définitions et propriétés', 2, 'On donne $\\vec{u}\\cdot\\vec{v} = -4$, $\\|\\vec{u}\\|^2 = 3$ et $\\|\\vec{v}\\|^2 = 9$. Calculer $(\\vec{u}+\\vec{v})\\cdot(\\vec{u}+\\vec{v})$.', '$(\\vec{u}+\\vec{v})\\cdot(\\vec{u}+\\vec{v}) = 4$', 'Développer comme une identité remarquable, en utilisant $\\vec{u}\\cdot\\vec{u} = \\|\\vec{u}\\|^2$.', ('Étape 1 : On développe : $(\\vec{u}+\\vec{v})\\cdot(\\vec{u}+\\vec{v}) = \\|\\vec{u}\\|^2 + 2\\,\\vec{u}\\cdot\\vec{v} + \\|\\vec{v}\\|^2$.', 'Étape 2 : $= 3 + 2\\times-4 + 9 = 4$.')),
    (2098, 'Autres définitions et propriétés', 1, 'On donne $\\vec{u}\\cdot\\vec{v} = 5$, $\\|\\vec{u}\\|^2 = 2$ et $\\|\\vec{v}\\|^2 = 6$. Calculer $(\\vec{u}+\\vec{v})\\cdot(\\vec{u}+\\vec{v})$.', '$(\\vec{u}+\\vec{v})\\cdot(\\vec{u}+\\vec{v}) = 18$', 'Développer comme une identité remarquable, en utilisant $\\vec{u}\\cdot\\vec{u} = \\|\\vec{u}\\|^2$.', ('Étape 1 : On développe : $(\\vec{u}+\\vec{v})\\cdot(\\vec{u}+\\vec{v}) = \\|\\vec{u}\\|^2 + 2\\,\\vec{u}\\cdot\\vec{v} + \\|\\vec{v}\\|^2$.', 'Étape 2 : $= 2 + 2\\times5 + 6 = 18$.')),
    (2099, 'Autres définitions et propriétés', 1, 'On donne $\\|\\vec{u}\\|^2 = 11$ et $\\|\\vec{v}\\|^2 = 4$. Calculer $(\\vec{u}+\\vec{v})\\cdot(\\vec{u}-\\vec{v})$.', '$(\\vec{u}+\\vec{v})\\cdot(\\vec{u}-\\vec{v}) = 7$', 'Développer comme une identité remarquable, en utilisant $\\vec{u}\\cdot\\vec{u} = \\|\\vec{u}\\|^2$.', ('Étape 1 : On développe : $(\\vec{u}+\\vec{v})\\cdot(\\vec{u}-\\vec{v}) = \\|\\vec{u}\\|^2 - \\|\\vec{v}\\|^2$.', 'Étape 2 : $= 11 - 4 = 7$.')),
    (2100, 'Autres définitions et propriétés', 2, 'On donne $\\|\\vec{u}\\|^2 = 9$ et $\\|\\vec{v}\\|^2 = 13$. Calculer $(\\vec{u}+\\vec{v})\\cdot(\\vec{u}-\\vec{v})$.', '$(\\vec{u}+\\vec{v})\\cdot(\\vec{u}-\\vec{v}) = -4$', 'Développer comme une identité remarquable, en utilisant $\\vec{u}\\cdot\\vec{u} = \\|\\vec{u}\\|^2$.', ('Étape 1 : On développe : $(\\vec{u}+\\vec{v})\\cdot(\\vec{u}-\\vec{v}) = \\|\\vec{u}\\|^2 - \\|\\vec{v}\\|^2$.', 'Étape 2 : $= 9 - 13 = -4$.')),
    (2101, 'Autres définitions et propriétés', 2, 'Deux vecteurs $\\vec{u}$ et $\\vec{v}$ vérifient $\\|\\vec{u}\\| = 3$, $\\|\\vec{v}\\| = 4$ et $\\left(\\vec{u} ; \\vec{v}\\right) = \\dfrac{\\pi}{3}$ (angle géométrique). Calculer $\\|\\vec{u}+\\vec{v}\\|$.', '$\\|\\vec{u}+\\vec{v}\\| = \\sqrt{37}$', 'Utiliser $\\|\\vec{u}+\\vec{v}\\|^2 = \\|\\vec{u}\\|^2 + 2\\,\\vec{u}\\cdot\\vec{v} + \\|\\vec{v}\\|^2$, puis prendre la racine carrée.', ('Étape 1 : $\\|\\vec{u}+\\vec{v}\\|^2 = \\|\\vec{u}\\|^2 + 2\\,\\vec{u}\\cdot\\vec{v} + \\|\\vec{v}\\|^2$.', 'Étape 2 : $\\vec{u}\\cdot\\vec{v} = 3\\times4\\times\\cos\\left(\\dfrac{\\pi}{3}\\right) = 6$.', 'Étape 3 : $\\|\\vec{u}+\\vec{v}\\|^2 = 3^2 + 2\\times(6) + 4^2 = 37$, donc $\\|\\vec{u}+\\vec{v}\\| = \\sqrt{37}$.')),
    (2102, 'Autres définitions et propriétés', 3, 'Deux vecteurs $\\vec{u}$ et $\\vec{v}$ vérifient $\\|\\vec{u}\\| = 6$, $\\|\\vec{v}\\| = 6$ et $\\left(\\vec{u} ; \\vec{v}\\right) = \\dfrac{\\pi}{3}$ (angle géométrique). Calculer $\\|\\vec{u}+\\vec{v}\\|$.', '$\\|\\vec{u}+\\vec{v}\\| = 6 \\sqrt{3}$', 'Utiliser $\\|\\vec{u}+\\vec{v}\\|^2 = \\|\\vec{u}\\|^2 + 2\\,\\vec{u}\\cdot\\vec{v} + \\|\\vec{v}\\|^2$, puis prendre la racine carrée.', ('Étape 1 : $\\|\\vec{u}+\\vec{v}\\|^2 = \\|\\vec{u}\\|^2 + 2\\,\\vec{u}\\cdot\\vec{v} + \\|\\vec{v}\\|^2$.', 'Étape 2 : $\\vec{u}\\cdot\\vec{v} = 6\\times6\\times\\cos\\left(\\dfrac{\\pi}{3}\\right) = 18$.', 'Étape 3 : $\\|\\vec{u}+\\vec{v}\\|^2 = 6^2 + 2\\times(18) + 6^2 = 108$, donc $\\|\\vec{u}+\\vec{v}\\| = \\sqrt{108} = 6 \\sqrt{3}$.')),
    (2103, 'Autres définitions et propriétés', 2, 'Deux vecteurs $\\vec{u}$ et $\\vec{v}$ vérifient $\\|\\vec{u}\\| = 5$, $\\|\\vec{v}\\| = 12$ et $\\left(\\vec{u} ; \\vec{v}\\right) = \\dfrac{\\pi}{2}$ (angle géométrique). Calculer $\\|\\vec{u}+\\vec{v}\\|$.', '$\\|\\vec{u}+\\vec{v}\\| = 13$', 'Utiliser $\\|\\vec{u}+\\vec{v}\\|^2 = \\|\\vec{u}\\|^2 + 2\\,\\vec{u}\\cdot\\vec{v} + \\|\\vec{v}\\|^2$, puis prendre la racine carrée.', ('Étape 1 : $\\|\\vec{u}+\\vec{v}\\|^2 = \\|\\vec{u}\\|^2 + 2\\,\\vec{u}\\cdot\\vec{v} + \\|\\vec{v}\\|^2$.', 'Étape 2 : $\\vec{u}\\cdot\\vec{v} = 5\\times12\\times\\cos\\left(\\dfrac{\\pi}{2}\\right) = 0$.', 'Étape 3 : $\\|\\vec{u}+\\vec{v}\\|^2 = 5^2 + 2\\times(0) + 12^2 = 169$, donc $\\|\\vec{u}+\\vec{v}\\| = \\sqrt{169} = 13$.')),
    (2104, 'Autres définitions et propriétés', 3, 'Deux vecteurs $\\vec{u}$ et $\\vec{v}$ vérifient $\\vec{u}\\cdot\\vec{v} = 12$, $\\|\\vec{u}\\| = 4$ et $\\left(\\vec{u} ; \\vec{v}\\right) = \\dfrac{\\pi}{3}$ (angle géométrique). En déduire $\\|\\vec{v}\\|$.', '$\\|\\vec{v}\\| = 6$', 'Repartir de $\\vec{u}\\cdot\\vec{v} = \\|\\vec{u}\\|\\,\\|\\vec{v}\\|\\cos(\\vec{u},\\vec{v})$ et isoler $\\|\\vec{v}\\|$.', ('Étape 1 : $\\vec{u}\\cdot\\vec{v} = \\|\\vec{u}\\|\\times\\|\\vec{v}\\|\\times\\cos(\\vec{u},\\vec{v})$, donc $\\|\\vec{v}\\| = \\dfrac{\\vec{u}\\cdot\\vec{v}}{\\|\\vec{u}\\|\\times\\cos(\\vec{u},\\vec{v})}$.', 'Étape 2 : $\\cos\\left(\\dfrac{\\pi}{3}\\right) = \\dfrac{1}{2}$, donc $\\|\\vec{v}\\| = \\dfrac{12}{4\\times\\dfrac{1}{2}} = 6$.')),
    (2105, 'Autres définitions et propriétés', 3, 'Deux vecteurs $\\vec{u}$ et $\\vec{v}$ vérifient $\\vec{u}\\cdot\\vec{v} = -9$, $\\|\\vec{u}\\| = 6$ et $\\left(\\vec{u} ; \\vec{v}\\right) = \\dfrac{2\\pi}{3}$ (angle géométrique). En déduire $\\|\\vec{v}\\|$.', '$\\|\\vec{v}\\| = 3$', 'Repartir de $\\vec{u}\\cdot\\vec{v} = \\|\\vec{u}\\|\\,\\|\\vec{v}\\|\\cos(\\vec{u},\\vec{v})$ et isoler $\\|\\vec{v}\\|$.', ('Étape 1 : $\\vec{u}\\cdot\\vec{v} = \\|\\vec{u}\\|\\times\\|\\vec{v}\\|\\times\\cos(\\vec{u},\\vec{v})$, donc $\\|\\vec{v}\\| = \\dfrac{\\vec{u}\\cdot\\vec{v}}{\\|\\vec{u}\\|\\times\\cos(\\vec{u},\\vec{v})}$.', 'Étape 2 : $\\cos\\left(\\dfrac{2\\pi}{3}\\right) = -\\dfrac{1}{2}$, donc $\\|\\vec{v}\\| = \\dfrac{-9}{6\\times-\\dfrac{1}{2}} = 3$.')),
    (2106, 'Autres définitions et propriétés', 3, 'On donne $(\\vec{u}+\\vec{v})\\cdot(\\vec{u}+\\vec{v}) = 30$, $\\|\\vec{u}\\|^2 = 8$ et $\\|\\vec{v}\\|^2 = 10$. En déduire la valeur de $\\vec{u}\\cdot\\vec{v}$.', '$\\vec{u}\\cdot\\vec{v} = 6$', 'Repartir de $(\\vec{u}+\\vec{v})\\cdot(\\vec{u}+\\vec{v}) = \\|\\vec{u}\\|^2 + 2\\,\\vec{u}\\cdot\\vec{v} + \\|\\vec{v}\\|^2$ et isoler $\\vec{u}\\cdot\\vec{v}$.', ('Étape 1 : $(\\vec{u}+\\vec{v})\\cdot(\\vec{u}+\\vec{v}) = \\|\\vec{u}\\|^2 + 2\\,\\vec{u}\\cdot\\vec{v} + \\|\\vec{v}\\|^2$, donc $2\\,\\vec{u}\\cdot\\vec{v} = 30 - 8 - 10$.', 'Étape 2 : $2\\,\\vec{u}\\cdot\\vec{v} = 12$, donc $\\vec{u}\\cdot\\vec{v} = 6$.')),
    (2107, 'Autres définitions et propriétés', 2, 'On donne $(\\vec{u}+\\vec{v})\\cdot(\\vec{u}+\\vec{v}) = 14$, $\\|\\vec{u}\\|^2 = 5$ et $\\|\\vec{v}\\|^2 = 3$. En déduire la valeur de $\\vec{u}\\cdot\\vec{v}$.', '$\\vec{u}\\cdot\\vec{v} = 3$', 'Repartir de $(\\vec{u}+\\vec{v})\\cdot(\\vec{u}+\\vec{v}) = \\|\\vec{u}\\|^2 + 2\\,\\vec{u}\\cdot\\vec{v} + \\|\\vec{v}\\|^2$ et isoler $\\vec{u}\\cdot\\vec{v}$.', ('Étape 1 : $(\\vec{u}+\\vec{v})\\cdot(\\vec{u}+\\vec{v}) = \\|\\vec{u}\\|^2 + 2\\,\\vec{u}\\cdot\\vec{v} + \\|\\vec{v}\\|^2$, donc $2\\,\\vec{u}\\cdot\\vec{v} = 14 - 5 - 3$.', 'Étape 2 : $2\\,\\vec{u}\\cdot\\vec{v} = 6$, donc $\\vec{u}\\cdot\\vec{v} = 3$.')),
    (2108, 'Autres définitions et propriétés', 3, 'Vrai ou faux ? On donne $\\vec{u}\\cdot\\vec{v} = 4$, $\\|\\vec{u}\\|^2 = 9$ et $\\|\\vec{v}\\|^2 = 5$. Affirmation : « $(\\vec{u}+\\vec{v})\\cdot(\\vec{u}-\\vec{v}) = 4$, car ce terme dépend de $\\vec{u}\\cdot\\vec{v}$ ». Justifier.', 'Faux', 'Cette expression ne dépend que de $\\|\\vec{u}\\|^2$ et $\\|\\vec{v}\\|^2$, jamais de $\\vec{u}\\cdot\\vec{v}$.', ("Étape 1 : $(\\vec{u}+\\vec{v})\\cdot(\\vec{u}-\\vec{v}) = \\|\\vec{u}\\|^2 - \\|\\vec{v}\\|^2$ : cette identité ne fait jamais intervenir $\\vec{u}\\cdot\\vec{v}$, contrairement à ce qu'affirme l'énoncé.", "Étape 2 : Numériquement, $\\|\\vec{u}\\|^2 - \\|\\vec{v}\\|^2 = 9 - 5 = 4$ : le résultat $4$ est donc correct, mais la justification de l'énoncé (« car ce terme dépend de $\\vec{u}\\cdot\\vec{v}$ ») est fausse.", "Étape 3 : L'affirmation est donc fausse, car sa justification est incorrecte : $\\vec{u}\\cdot\\vec{v}$ n'intervient jamais dans $(\\vec{u}+\\vec{v})\\cdot(\\vec{u}-\\vec{v})$, même si la valeur numérique $4$ coïncide ici.")),
    (2109, 'Autres définitions et propriétés', 2, 'Vrai ou faux ? Si $\\vec{u}\\cdot\\vec{v} = 0$ avec $\\vec{u}$ et $\\vec{v}$ non nuls, alors $(\\vec{u}+\\vec{v})\\cdot(\\vec{u}+\\vec{v}) = \\|\\vec{u}\\|^2+\\|\\vec{v}\\|^2$. Justifier.', 'Vrai', 'Développer $(\\vec{u}+\\vec{v})\\cdot(\\vec{u}+\\vec{v})$ et remplacer $\\vec{u}\\cdot\\vec{v}$ par $0$.', ('Étape 1 : $(\\vec{u}+\\vec{v})\\cdot(\\vec{u}+\\vec{v}) = \\|\\vec{u}\\|^2 + 2\\,\\vec{u}\\cdot\\vec{v} + \\|\\vec{v}\\|^2$.', 'Étape 2 : Comme $\\vec{u}\\cdot\\vec{v} = 0$, le terme central disparaît : $(\\vec{u}+\\vec{v})\\cdot(\\vec{u}+\\vec{v}) = \\|\\vec{u}\\|^2 + \\|\\vec{v}\\|^2$.', "Étape 3 : L'affirmation est donc vraie ; c'est le théorème de Pythagore reformulé avec le produit scalaire.")),
    (2110, 'Autres définitions et propriétés', 2, 'Un élève affirme : « $\\vec{u}\\cdot\\vec{v} = -7$, $\\|\\vec{u}\\|^2 = 6$ et $\\|\\vec{v}\\|^2 = 3$, donc $(\\vec{u}+\\vec{v})\\cdot(\\vec{u}+\\vec{v}) = 6 + (-7) + 3 = 2$ ». Identifier et corriger son erreur.', '$(\\vec{u}+\\vec{v})\\cdot(\\vec{u}+\\vec{v}) = -5$', 'Le terme croisé $\\vec{u}\\cdot\\vec{v}$ doit être compté deux fois dans le développement.', ("Étape 1 : La formule correcte est $(\\vec{u}+\\vec{v})\\cdot(\\vec{u}+\\vec{v}) = \\|\\vec{u}\\|^2 + 2\\,\\vec{u}\\cdot\\vec{v} + \\|\\vec{v}\\|^2$ : l'élève a oublié le facteur $2$ devant $\\vec{u}\\cdot\\vec{v}$.", 'Étape 2 : Le calcul correct est $6 + 2\\times(-7) + 3 = 6 - 14 + 3 = -5$.', 'Étape 3 : Le résultat correct est donc $(\\vec{u}+\\vec{v})\\cdot(\\vec{u}+\\vec{v}) = -5$, et non $2$.')),
    (2111, 'Autres définitions et propriétés', 2, 'Un élève affirme : « $\\|\\vec{u}\\| = 6$, $\\|\\vec{v}\\| = 4$, $\\left(\\vec{u};\\vec{v}\\right) = \\dfrac{\\pi}{3}$, donc $\\vec{u}\\cdot\\vec{v} = 6\\times4\\times\\dfrac{\\sqrt{3}}{2} = 12\\sqrt{3}$ ». Identifier et corriger son erreur.', '$\\vec{u}\\cdot\\vec{v} = 12$', 'Vérifier la valeur exacte de $\\cos\\left(\\dfrac{\\pi}{3}\\right)$.', ("Étape 1 : L'élève confond $\\cos\\left(\\dfrac{\\pi}{3}\\right)$ avec $\\cos\\left(\\dfrac{\\pi}{6}\\right) = \\dfrac{\\sqrt{3}}{2}$. Or $\\cos\\left(\\dfrac{\\pi}{3}\\right) = \\dfrac{1}{2}$.", 'Étape 2 : Le calcul correct est $\\vec{u}\\cdot\\vec{v} = 6\\times4\\times\\dfrac{1}{2} = 12$.', 'Étape 3 : Le résultat correct est donc $\\vec{u}\\cdot\\vec{v} = 12$, et non $12\\sqrt{3}$.')),
    (2112, 'Autres définitions et propriétés', 4, 'Soit $\\vec{u}$ et $\\vec{v}$ deux vecteurs du plan. Démontrer que $(\\vec{u}+\\vec{v})\\cdot(\\vec{u}+\\vec{v}) + (\\vec{u}-\\vec{v})\\cdot(\\vec{u}-\\vec{v}) = 2\\left(\\|\\vec{u}\\|^2+\\|\\vec{v}\\|^2\\right)$ (identité du parallélogramme).', 'Identité démontrée : $(\\vec{u}+\\vec{v})\\cdot(\\vec{u}+\\vec{v}) + (\\vec{u}-\\vec{v})\\cdot(\\vec{u}-\\vec{v}) = 2\\|\\vec{u}\\|^2+2\\|\\vec{v}\\|^2$', "Développer séparément chaque produit scalaire à l'aide des identités remarquables, puis additionner.", ('Étape 1 : $(\\vec{u}+\\vec{v})\\cdot(\\vec{u}+\\vec{v}) = \\|\\vec{u}\\|^2 + 2\\,\\vec{u}\\cdot\\vec{v} + \\|\\vec{v}\\|^2$.', 'Étape 2 : $(\\vec{u}-\\vec{v})\\cdot(\\vec{u}-\\vec{v}) = \\|\\vec{u}\\|^2 - 2\\,\\vec{u}\\cdot\\vec{v} + \\|\\vec{v}\\|^2$.', "Étape 3 : En additionnant les deux expressions, les termes en $\\vec{u}\\cdot\\vec{v}$ s'annulent : $\\left(\\|\\vec{u}\\|^2 + 2\\,\\vec{u}\\cdot\\vec{v} + \\|\\vec{v}\\|^2\\right) + \\left(\\|\\vec{u}\\|^2 - 2\\,\\vec{u}\\cdot\\vec{v} + \\|\\vec{v}\\|^2\\right) = 2\\|\\vec{u}\\|^2+2\\|\\vec{v}\\|^2$, ce qui prouve l'identité.")),
    (2113, 'Autres définitions et propriétés', 4, "On donne $\\|\\vec{u}\\| = 6$, $\\|\\vec{v}\\| = 8$ et $\\left(\\vec{u};\\vec{v}\\right) = \\dfrac{\\pi}{3}$. Un élève calcule $\\vec{u}\\cdot\\vec{v}$ avec la formule $\\|\\vec{u}\\|\\,\\|\\vec{v}\\|\\cos(\\vec{u},\\vec{v})$, un autre calcule d'abord $\\|\\vec{u}+\\vec{v}\\|^2$ puis en déduit $\\vec{u}\\cdot\\vec{v}$ grâce à $\\|\\vec{u}+\\vec{v}\\|^2 = \\|\\vec{u}\\|^2+2\\vec{u}\\cdot\\vec{v}+\\|\\vec{v}\\|^2$, sachant que $\\|\\vec{u}+\\vec{v}\\| = 2\\sqrt{37}$. Comparer les deux méthodes et vérifier qu'elles donnent le même résultat.", 'Les deux méthodes donnent $\\vec{u}\\cdot\\vec{v} = 24$', 'Isoler $\\vec{u}\\cdot\\vec{v}$ dans la seconde formule et comparer au résultat de la première.', ('Étape 1 (méthode directe) : $\\vec{u}\\cdot\\vec{v} = 6\\times8\\times\\cos\\left(\\dfrac{\\pi}{3}\\right) = 48\\times\\dfrac{1}{2} = 24$.', 'Étape 2 (méthode indirecte) : $\\|\\vec{u}+\\vec{v}\\|^2 = \\left(2\\sqrt{37}\\right)^2 = 148$, et $\\|\\vec{u}+\\vec{v}\\|^2 = \\|\\vec{u}\\|^2+2\\vec{u}\\cdot\\vec{v}+\\|\\vec{v}\\|^2 = 36+2\\vec{u}\\cdot\\vec{v}+64$.', 'Étape 3 : $148 = 100 + 2\\,\\vec{u}\\cdot\\vec{v}$, donc $\\vec{u}\\cdot\\vec{v} = 24$. Les deux méthodes donnent bien le même résultat, ce qui confirme leur cohérence.')),
    (2114, 'Autres définitions et propriétés', 2, 'Un traîneau est tiré par une force $\\vec{F}$ de norme $\\|\\vec{F}\\| = 120$ N, faisant un angle de $\\dfrac{\\pi}{3}$ avec le déplacement $\\vec{d}$, de norme $\\|\\vec{d}\\| = 15$ m. Le travail de la force vaut $W = \\vec{F}\\cdot\\vec{d}$ (en joules). Calculer $W$.', '$W = 900$ J', "Le travail d'une force est le produit scalaire $\\vec{F}\\cdot\\vec{d} = \\|\\vec{F}\\|\\,\\|\\vec{d}\\|\\cos(\\vec{F},\\vec{d})$.", ('Étape 1 : $W = \\vec{F}\\cdot\\vec{d} = \\|\\vec{F}\\|\\times\\|\\vec{d}\\|\\times\\cos\\left(\\dfrac{\\pi}{3}\\right)$.', 'Étape 2 : $W = 120\\times15\\times\\dfrac{1}{2} = 1800\\times\\dfrac{1}{2} = 900$.', 'Étape 3 : Le travail de la force vaut donc $W = 900$ J.')),
    (2115, 'Autres définitions et propriétés', 3, 'Un skieur est tracté par une remontée mécanique : la force de traction $\\vec{F}$ a pour norme $80$ N et fait un angle de $\\dfrac{\\pi}{4}$ avec le déplacement $\\vec{d}$ de norme $200$ m. Sachant que le travail vaut $W = \\vec{F}\\cdot\\vec{d}$, calculer $W$ (en joules), en donnant la valeur exacte puis une valeur arrondie au joule près.', '$W = 8000\\sqrt{2}$ J $\\approx 11314$ J', 'Utiliser $W = \\|\\vec{F}\\|\\,\\|\\vec{d}\\|\\cos(\\vec{F},\\vec{d})$ avec $\\cos\\left(\\dfrac{\\pi}{4}\\right) = \\dfrac{\\sqrt{2}}{2}$.', ('Étape 1 : $W = 80\\times200\\times\\cos\\left(\\dfrac{\\pi}{4}\\right) = 16000\\times\\dfrac{\\sqrt{2}}{2} = 8000\\sqrt{2}$.', 'Étape 2 : $8000\\sqrt{2} \\approx 11313{,}7$, soit environ $11314$ J au joule près.')),
    (2116, 'Produit scalaire, colinéarité et orthogonalité de vecteurs', 1, 'Dans un repère orthonormé, on donne les vecteurs $\\vec{u}(3 ; -2)$ et $\\vec{v}(5 ; 4)$. Calculer le produit scalaire $\\vec{u} \\cdot \\vec{v}$.', '$\\vec{u}\\cdot\\vec{v} = 7$', 'Utiliser $\\vec{u}\\cdot\\vec{v} = x_u x_v + y_u y_v$.', ('Étape 1 : $\\vec{u}\\cdot\\vec{v} = x_u\\times x_v + y_u\\times y_v$.', 'Étape 2 : $\\vec{u}\\cdot\\vec{v} = 3\\times5 + -2\\times4 = 7$.')),
    (2117, 'Produit scalaire, colinéarité et orthogonalité de vecteurs', 2, 'Dans un repère orthonormé, on donne les vecteurs $\\vec{u}(-7 ; 1)$ et $\\vec{v}(2 ; -3)$. Calculer le produit scalaire $\\vec{u} \\cdot \\vec{v}$.', '$\\vec{u}\\cdot\\vec{v} = -17$', 'Utiliser $\\vec{u}\\cdot\\vec{v} = x_u x_v + y_u y_v$.', ('Étape 1 : $\\vec{u}\\cdot\\vec{v} = x_u\\times x_v + y_u\\times y_v$.', 'Étape 2 : $\\vec{u}\\cdot\\vec{v} = -7\\times2 + 1\\times-3 = -17$.')),
    (2118, 'Produit scalaire, colinéarité et orthogonalité de vecteurs', 1, 'Dans un repère orthonormé, on donne les vecteurs $\\vec{u}(4 ; 6)$ et $\\vec{v}(-1 ; 5)$. Calculer le produit scalaire $\\vec{u} \\cdot \\vec{v}$.', '$\\vec{u}\\cdot\\vec{v} = 26$', 'Utiliser $\\vec{u}\\cdot\\vec{v} = x_u x_v + y_u y_v$.', ('Étape 1 : $\\vec{u}\\cdot\\vec{v} = x_u\\times x_v + y_u\\times y_v$.', 'Étape 2 : $\\vec{u}\\cdot\\vec{v} = 4\\times-1 + 6\\times5 = 26$.')),
    (2119, 'Produit scalaire, colinéarité et orthogonalité de vecteurs', 1, 'Dans un repère orthonormé, on donne les vecteurs $\\vec{u}(3 ; -5)$ et $\\vec{v}(4 ; k)$. Déterminer la valeur de $k$ pour laquelle $\\vec{u}$ et $\\vec{v}$ sont orthogonaux.', '$k = \\dfrac{12}{5}$', 'Deux vecteurs sont orthogonaux si, et seulement si, $\\vec{u}\\cdot\\vec{v}=0$.', ('Étape 1 : Deux vecteurs sont orthogonaux si, et seulement si, leur produit scalaire est nul.', 'Étape 2 : $\\vec{u}\\cdot\\vec{v} = 3\\times4 + -5\\times k = 0$.', 'Étape 3 : $12 + -5k = 0 \\iff k = \\dfrac{12}{5}$.')),
    (2120, 'Produit scalaire, colinéarité et orthogonalité de vecteurs', 2, 'Dans un repère orthonormé, on donne les vecteurs $\\vec{u}(-2 ; 7)$ et $\\vec{v}(6 ; k)$. Déterminer la valeur de $k$ pour laquelle $\\vec{u}$ et $\\vec{v}$ sont orthogonaux.', '$k = \\dfrac{12}{7}$', 'Deux vecteurs sont orthogonaux si, et seulement si, $\\vec{u}\\cdot\\vec{v}=0$.', ('Étape 1 : Deux vecteurs sont orthogonaux si, et seulement si, leur produit scalaire est nul.', 'Étape 2 : $\\vec{u}\\cdot\\vec{v} = -2\\times6 + 7\\times k = 0$.', 'Étape 3 : $-12 + 7k = 0 \\iff k = \\dfrac{12}{7}$.')),
    (2121, 'Produit scalaire, colinéarité et orthogonalité de vecteurs', 1, 'Dans un repère orthonormé, on donne les vecteurs $\\vec{u}(-3 ; 4)$ et $\\vec{v}(6 ; k)$. Déterminer la valeur de $k$ pour laquelle $\\vec{u}$ et $\\vec{v}$ sont colinéaires.', '$k = -8$', 'Deux vecteurs sont colinéaires si, et seulement si, $x_u y_v - x_v y_u = 0$.', ('Étape 1 : Deux vecteurs sont colinéaires si, et seulement si, $x_u y_v - x_v y_u = 0$.', 'Étape 2 : $-3\\times k - (6)\\times(4) = 0$.', 'Étape 3 : $-3k = 24 \\iff k = -8$.')),
    (2122, 'Produit scalaire, colinéarité et orthogonalité de vecteurs', 2, 'Dans un repère orthonormé, on donne les vecteurs $\\vec{u}(5 ; -2)$ et $\\vec{v}(-4 ; k)$. Déterminer la valeur de $k$ pour laquelle $\\vec{u}$ et $\\vec{v}$ sont colinéaires.', '$k = \\dfrac{8}{5}$', 'Deux vecteurs sont colinéaires si, et seulement si, $x_u y_v - x_v y_u = 0$.', ('Étape 1 : Deux vecteurs sont colinéaires si, et seulement si, $x_u y_v - x_v y_u = 0$.', 'Étape 2 : $5\\times k - (-4)\\times(-2) = 0$.', 'Étape 3 : $5k = 8 \\iff k = \\dfrac{8}{5}$.')),
    (2123, 'Produit scalaire, colinéarité et orthogonalité de vecteurs', 2, 'On donne les points $A(1 ; 2)$, $B(4 ; 6)$, $C(-1 ; 3)$ et $D(2 ; -1)$. Calculer le produit scalaire $\\vec{AB}\\cdot\\vec{CD}$.', '$\\vec{AB}\\cdot\\vec{CD} = -7$', "Calculer d'abord les coordonnées des vecteurs $\\vec{AB}$ et $\\vec{CD}$, puis appliquer $\\vec{AB}\\cdot\\vec{CD} = x_{AB}x_{CD}+y_{AB}y_{CD}$.", ('Étape 1 : $\\vec{AB}(3 ; 4)$ et $\\vec{CD}(3 ; -4)$.', 'Étape 2 : $\\vec{AB}\\cdot\\vec{CD} = 3\\times3 + 4\\times-4 = -7$.')),
    (2124, 'Produit scalaire, colinéarité et orthogonalité de vecteurs', 3, 'On donne les points $A(-3 ; 0)$, $B(1 ; 3)$, $C(2 ; 5)$ et $D(-2 ; 1)$. Calculer le produit scalaire $\\vec{AB}\\cdot\\vec{CD}$.', '$\\vec{AB}\\cdot\\vec{CD} = -28$', "Calculer d'abord les coordonnées des vecteurs $\\vec{AB}$ et $\\vec{CD}$, puis appliquer $\\vec{AB}\\cdot\\vec{CD} = x_{AB}x_{CD}+y_{AB}y_{CD}$.", ('Étape 1 : $\\vec{AB}(4 ; 3)$ et $\\vec{CD}(-4 ; -4)$.', 'Étape 2 : $\\vec{AB}\\cdot\\vec{CD} = 4\\times-4 + 3\\times-4 = -28$.')),
    (2125, 'Produit scalaire, colinéarité et orthogonalité de vecteurs', 2, 'On donne les points $A(0 ; -2)$, $B(3 ; 2)$, $C(-4 ; 1)$ et $D(-1 ; 4)$. Calculer le produit scalaire $\\vec{AB}\\cdot\\vec{CD}$.', '$\\vec{AB}\\cdot\\vec{CD} = 21$', "Calculer d'abord les coordonnées des vecteurs $\\vec{AB}$ et $\\vec{CD}$, puis appliquer $\\vec{AB}\\cdot\\vec{CD} = x_{AB}x_{CD}+y_{AB}y_{CD}$.", ('Étape 1 : $\\vec{AB}(3 ; 4)$ et $\\vec{CD}(3 ; 3)$.', 'Étape 2 : $\\vec{AB}\\cdot\\vec{CD} = 3\\times3 + 4\\times3 = 21$.')),
    (2126, 'Produit scalaire, colinéarité et orthogonalité de vecteurs', 2, 'Dans un repère orthonormé, les vecteurs $\\vec{u}(p ; -6)$ et $\\vec{v}(3 ; 4)$ sont orthogonaux. Déterminer $p$.', '$p = 8$', "Deux vecteurs sont orthogonaux si, et seulement si, $\\vec{u}\\cdot\\vec{v}=0$ ; ici l'inconnue est la première coordonnée.", ('Étape 1 : $\\vec{u}\\cdot\\vec{v} = p\\times3 + (-6)\\times(4) = 0$.', 'Étape 2 : $3p - 24 = 0 \\iff p = 8$.')),
    (2127, 'Produit scalaire, colinéarité et orthogonalité de vecteurs', 3, 'Dans un repère orthonormé, les vecteurs $\\vec{u}(p ; 2)$ et $\\vec{v}(10 ; -5)$ sont orthogonaux. Déterminer $p$.', '$p = 1$', "Deux vecteurs sont orthogonaux si, et seulement si, $\\vec{u}\\cdot\\vec{v}=0$ ; ici l'inconnue est la première coordonnée.", ('Étape 1 : $\\vec{u}\\cdot\\vec{v} = p\\times10 + (2)\\times(-5) = 0$.', 'Étape 2 : $10p - 10 = 0 \\iff p = 1$.')),
    (2128, 'Produit scalaire, colinéarité et orthogonalité de vecteurs', 2, 'Vrai ou faux ? Dans un repère orthonormé, les vecteurs $\\vec{u}(4 ; -6)$ et $\\vec{v}(-6 ; 9)$ sont colinéaires. Justifier.', 'Vrai', 'Calculer $x_u y_v - x_v y_u$ : les vecteurs sont colinéaires si, et seulement si, cette quantité est nulle.', ('Étape 1 : $x_u y_v - x_v y_u = 4\\times9 - (-6)\\times(-6) = 36 - 36 = 0$.', "Étape 2 : Le résultat est nul, donc $\\vec{u}$ et $\\vec{v}$ sont colinéaires (on remarque d'ailleurs que $\\vec{v} = -\\dfrac{3}{2}\\vec{u}$). L'affirmation est donc vraie.")),
    (2129, 'Produit scalaire, colinéarité et orthogonalité de vecteurs', 2, 'Vrai ou faux ? Dans un repère orthonormé, les vecteurs $\\vec{u}(2 ; 5)$ et $\\vec{v}(-3 ; 7)$ sont colinéaires. Justifier.', 'Faux', 'Calculer $x_u y_v - x_v y_u$ : les vecteurs sont colinéaires si, et seulement si, cette quantité est nulle.', ('Étape 1 : $x_u y_v - x_v y_u = 2\\times7 - (-3)\\times5 = 14 + 15 = 29$.', "Étape 2 : Le résultat n'est pas nul, donc $\\vec{u}$ et $\\vec{v}$ ne sont pas colinéaires. L'affirmation est donc fausse.")),
    (2130, 'Produit scalaire, colinéarité et orthogonalité de vecteurs', 3, 'Vrai ou faux ? Si deux vecteurs non nuls $\\vec{u}$ et $\\vec{v}$ sont orthogonaux, alors ils sont colinéaires. Justifier.', 'Faux', "Comparer les définitions de l'orthogonalité ($\\vec{u}\\cdot\\vec{v}=0$) et de la colinéarité ($x_u y_v - x_v y_u = 0$) sur un exemple.", ('Étape 1 : Prenons $\\vec{u}(1 ; 0)$ et $\\vec{v}(0 ; 1)$. On a $\\vec{u}\\cdot\\vec{v} = 1\\times0+0\\times1 = 0$ : les deux vecteurs sont orthogonaux.', 'Étape 2 : Or $x_u y_v - x_v y_u = 1\\times1 - 0\\times0 = 1 \\neq 0$ : ils ne sont pas colinéaires.', "Étape 3 : Deux vecteurs orthogonaux non nuls ne sont donc jamais colinéaires (sauf cas dégénéré exclu ici) : l'affirmation est fausse. Orthogonalité et colinéarité sont deux notions distinctes et incompatibles pour des vecteurs non nuls.")),
    (2131, 'Produit scalaire, colinéarité et orthogonalité de vecteurs', 2, 'Un élève calcule le produit scalaire de $\\vec{u}(3 ; -4)$ et $\\vec{v}(2 ; 5)$ ainsi : « $\\vec{u}\\cdot\\vec{v} = (3+2)\\times(-4+5) = 5$ ». Identifier et corriger son erreur.', '$\\vec{u}\\cdot\\vec{v} = -14$', 'Le produit scalaire se calcule coordonnée par coordonnée, pas en additionnant puis en multipliant les sommes.', ('Étape 1 : La formule correcte est $\\vec{u}\\cdot\\vec{v} = x_u x_v + y_u y_v$, et non $(x_u+x_v)(y_u+y_v)$.', 'Étape 2 : Le calcul correct est $\\vec{u}\\cdot\\vec{v} = 3\\times2 + (-4)\\times5 = 6 - 20 = -14$.', 'Étape 3 : Le résultat correct est donc $\\vec{u}\\cdot\\vec{v} = -14$, et non $5$.')),
    (2132, 'Produit scalaire, colinéarité et orthogonalité de vecteurs', 3, 'Pour montrer que $\\vec{u}(-2 ; 6)$ et $\\vec{v}(3 ; 1)$ sont colinéaires, un élève écrit : « $x_u x_v - y_u y_v = -2\\times3 - 6\\times1 = -12 \\neq 0$, donc ils ne sont pas colinéaires ». Identifier et corriger son erreur.', "$\\vec{u}$ et $\\vec{v}$ ne sont effectivement pas colinéaires, mais le critère utilisé par l'élève est faux", 'Le critère de colinéarité est $x_u y_v - x_v y_u$, pas $x_u x_v - y_u y_v$.', ("Étape 1 : L'élève a utilisé une formule incorrecte. Le bon critère est $x_u y_v - x_v y_u = 0$.", 'Étape 2 : Avec la bonne formule : $x_u y_v - x_v y_u = -2\\times1 - 3\\times6 = -2 - 18 = -20 \\neq 0$.', "Étape 3 : La conclusion de l'élève (les vecteurs ne sont pas colinéaires) est correcte par coïncidence, mais sa méthode était fausse : c'est la formule $x_u y_v - x_v y_u$ qu'il fallait utiliser, pas $x_u x_v - y_u y_v$.")),
    (2133, 'Produit scalaire, colinéarité et orthogonalité de vecteurs', 2, "On considère le triangle $A(1 ; 1)B(5 ; 1)C(5 ; 4)$. Ce triangle est-il rectangle en $B$ ? Justifier à l'aide d'un produit scalaire.", 'Le triangle $ABC$ est rectangle en $B$ car $\\vec{BA}\\cdot\\vec{BC} = 0$', 'Un triangle est rectangle en $B$ si, et seulement si, $\\vec{BA}\\cdot\\vec{BC} = 0$.', ('Étape 1 : $\\vec{BA}(-4 ; 0)$ et $\\vec{BC}(0 ; 3)$.', 'Étape 2 : $\\vec{BA}\\cdot\\vec{BC} = (-4)\\times(0) + (0)\\times(3) = 0$.', 'Étape 3 : Le produit scalaire est nul, donc $\\vec{BA}$ et $\\vec{BC}$ sont orthogonaux : le triangle $ABC$ est bien rectangle en $B$.')),
    (2134, 'Produit scalaire, colinéarité et orthogonalité de vecteurs', 3, "On considère le triangle $A(-2 ; -1)B(2 ; 2)C(4 ; 0)$. Ce triangle est-il rectangle en $B$ ? Justifier à l'aide d'un produit scalaire.", "Le triangle $ABC$ n'est pas rectangle en $B$ car $\\vec{BA}\\cdot\\vec{BC} = -2 \\neq 0$", 'Un triangle est rectangle en $B$ si, et seulement si, $\\vec{BA}\\cdot\\vec{BC} = 0$.', ('Étape 1 : $\\vec{BA}(-4 ; -3)$ et $\\vec{BC}(2 ; -2)$.', 'Étape 2 : $\\vec{BA}\\cdot\\vec{BC} = (-4)\\times(2) + (-3)\\times(-2) = -2$.', "Étape 3 : Le produit scalaire n'est pas nul, donc $\\vec{BA}$ et $\\vec{BC}$ ne sont pas orthogonaux : le triangle $ABC$ n'est pas rectangle en $B$.")),
    (2135, 'Produit scalaire, colinéarité et orthogonalité de vecteurs', 2, 'Deux routes sont modélisées, dans un repère orthonormé où les distances sont en kilomètres, par les vecteurs directeurs $\\vec{u}(3 ; 4)$ et $\\vec{v}(-4 ; 3)$. Ces deux routes sont-elles perpendiculaires ?', 'Oui, les deux routes sont perpendiculaires', 'Deux droites sont perpendiculaires si, et seulement si, leurs vecteurs directeurs sont orthogonaux.', ('Étape 1 : $\\vec{u}\\cdot\\vec{v} = 3\\times(-4) + 4\\times3 = -12+12 = 0$.', 'Étape 2 : Le produit scalaire est nul, donc $\\vec{u}$ et $\\vec{v}$ sont orthogonaux : les deux routes sont bien perpendiculaires.')),
    (2136, 'Produit scalaire, colinéarité et orthogonalité de vecteurs', 3, 'Un drone se déplace du point $A(2 ; 1)$ au point $B(6 ; 4)$, puis du point $B$ au point $C(9 ; 0)$ (coordonnées en centaines de mètres). Le pilote affirme avoir fait effectuer au drone un virage à angle droit en $B$. A-t-il raison ?', 'Oui, le pilote a raison : le virage en $B$ est bien à angle droit', 'Calculer $\\vec{BA}\\cdot\\vec{BC}$ : un virage à angle droit correspond à un produit scalaire nul.', ('Étape 1 : $\\vec{BA}(-4 ; -3)$ et $\\vec{BC}(3 ; -4)$.', 'Étape 2 : $\\vec{BA}\\cdot\\vec{BC} = -4\\times3 + (-3)\\times(-4) = -12+12 = 0$.', 'Étape 3 : Le produit scalaire est nul, donc $\\vec{BA}$ et $\\vec{BC}$ sont orthogonaux : le pilote a raison, le virage en $B$ est bien à angle droit.')),
    (2137, 'Produit scalaire, colinéarité et orthogonalité de vecteurs', 3, "Dans un repère orthonormé, on donne $\\vec{u}(4 ; -6)$ et $\\vec{v}(-2 ; 3)$. Un élève vérifie la colinéarité en calculant le déterminant $x_u y_v - x_v y_u$, un autre en cherchant un réel $k$ tel que $\\vec{v} = k\\vec{u}$. Mener les deux méthodes et vérifier qu'elles mènent à la même conclusion.", 'Les deux méthodes montrent que $\\vec{u}$ et $\\vec{v}$ sont colinéaires ($\\vec{v} = -\\dfrac{1}{2}\\vec{u}$)', "Le déterminant nul et l'existence d'un coefficient $k$ commun aux deux coordonnées traduisent la même propriété.", ('Étape 1 (déterminant) : $x_u y_v - x_v y_u = 4\\times3 - (-2)\\times(-6) = 12 - 12 = 0$, donc $\\vec{u}$ et $\\vec{v}$ sont colinéaires.', 'Étape 2 (coefficient de proportionnalité) : en comparant les coordonnées, $-2 = k\\times4$ donne $k = -\\dfrac{1}{2}$, et $3 = k\\times(-6)$ donne aussi $k = -\\dfrac{1}{2}$.', "Étape 3 : Les deux méthodes s'accordent : $\\vec{v} = -\\dfrac{1}{2}\\vec{u}$, donc les deux vecteurs sont bien colinéaires. La méthode du déterminant est plus rapide, celle du coefficient donne en plus la relation exacte entre les deux vecteurs.")),
    (2138, 'Produit scalaire, colinéarité et orthogonalité de vecteurs', 4, 'Soit $\\vec{u}(x_1 ; y_1)$ et $\\vec{v}(x_2 ; y_2)$ deux vecteurs non nuls du plan, avec $x_1 \\neq 0$. Démontrer que si $\\vec{u}$ et $\\vec{v}$ sont colinéaires, alors $x_1 y_2 - x_2 y_1 = 0$.', 'Propriété démontrée : $x_1 y_2 - x_2 y_1 = 0$ lorsque $\\vec{u}$ et $\\vec{v}$ sont colinéaires', 'Si $\\vec{u}$ et $\\vec{v}$ sont colinéaires, il existe un réel $k$ tel que $\\vec{v} = k\\vec{u}$ ; exprimer $x_2$ et $y_2$ en fonction de $k$, $x_1$ et $y_1$.', ("Étape 1 : Comme $\\vec{u}$ et $\\vec{v}$ sont colinéaires, il existe un réel $k$ tel que $\\vec{v} = k\\vec{u}$, c'est-à-dire $x_2 = kx_1$ et $y_2 = ky_1$.", 'Étape 2 : On calcule alors $x_1 y_2 - x_2 y_1 = x_1\\times(ky_1) - (kx_1)\\times y_1 = kx_1y_1 - kx_1y_1 = 0$.', 'Étape 3 : On obtient bien $x_1 y_2 - x_2 y_1 = 0$, ce qui démontre la propriété.')),
    (2181, "Étude d'un ensemble de points", 2, "On donne le point $A(3 ; -4)$ et le vecteur $\\vec{u}(2 ; 5)$. Déterminer, en la caractérisant géométriquement, l'ensemble des points $M(x;y)$ du plan tels que $\\vec{AM} \\cdot \\vec{u} = 0$.", "La droite passant par $A$ de vecteur normal $\\vec{u}$, d'équation $2x +5y +14 = 0$", '$\\vec{AM}\\cdot\\vec{u}=0$ signifie que $\\vec{AM}$ et $\\vec{u}$ sont orthogonaux.', ("Étape 1 : $\\vec{AM}\\cdot\\vec{u}=0$ signifie que $\\vec{u}$ est un vecteur normal à $\\vec{AM}$ : l'ensemble cherché est donc la droite passant par $A$ et de vecteur normal $\\vec{u}$.", 'Étape 2 : $\\vec{AM}(x-(3);y-(-4))$, donc $\\vec{AM}\\cdot\\vec{u} = 2(x-(3))+5(y-(-4))=0$.', "Étape 3 : En développant, on obtient l'équation $2x +5y +14 = 0$.")),
    (2182, "Étude d'un ensemble de points", 2, "On donne le point $A(-1 ; 2)$ et le vecteur $\\vec{u}(-6 ; 3)$. Déterminer, en la caractérisant géométriquement, l'ensemble des points $M(x;y)$ du plan tels que $\\vec{AM} \\cdot \\vec{u} = 0$.", "La droite passant par $A$ de vecteur normal $\\vec{u}$, d'équation $-6x +3y -12 = 0$", '$\\vec{AM}\\cdot\\vec{u}=0$ signifie que $\\vec{AM}$ et $\\vec{u}$ sont orthogonaux.', ("Étape 1 : $\\vec{AM}\\cdot\\vec{u}=0$ signifie que $\\vec{u}$ est un vecteur normal à $\\vec{AM}$ : l'ensemble cherché est donc la droite passant par $A$ et de vecteur normal $\\vec{u}$.", 'Étape 2 : $\\vec{AM}(x-(-1);y-(2))$, donc $\\vec{AM}\\cdot\\vec{u} = -6(x-(-1))+3(y-(2))=0$.', "Étape 3 : En développant, on obtient l'équation $-6x +3y -12 = 0$.")),
    (2183, "Étude d'un ensemble de points", 3, "On donne le point $A(0 ; 5)$ et le vecteur $\\vec{u}(4 ; -7)$. Déterminer, en la caractérisant géométriquement, l'ensemble des points $M(x;y)$ du plan tels que $\\vec{AM} \\cdot \\vec{u} = 0$.", "La droite passant par $A$ de vecteur normal $\\vec{u}$, d'équation $4x -7y +35 = 0$", '$\\vec{AM}\\cdot\\vec{u}=0$ signifie que $\\vec{AM}$ et $\\vec{u}$ sont orthogonaux.', ("Étape 1 : $\\vec{AM}\\cdot\\vec{u}=0$ signifie que $\\vec{u}$ est un vecteur normal à $\\vec{AM}$ : l'ensemble cherché est donc la droite passant par $A$ et de vecteur normal $\\vec{u}$.", 'Étape 2 : $\\vec{AM}(x-(0);y-(5))$, donc $\\vec{AM}\\cdot\\vec{u} = 4(x-(0))+-7(y-(5))=0$.', "Étape 3 : En développant, on obtient l'équation $4x -7y +35 = 0$.")),
    (2184, "Étude d'un ensemble de points", 2, "On donne les points $A(2 ; 5)$ et $B(-4 ; 1)$. Déterminer l'ensemble des points $M$ du plan tels que $\\vec{MA} \\cdot \\vec{MB} = 0$.", 'Le cercle de diamètre $[AB]$, de centre $\\Omega\\left(-1 ; 3\\right)$ et de rayon $\\sqrt{13}$', '$\\vec{MA}\\cdot\\vec{MB}=0$ signifie que $M$ voit $[AB]$ sous un angle droit.', ("Étape 1 : $\\vec{MA}\\cdot\\vec{MB}=0$ signifie que $\\vec{MA}$ et $\\vec{MB}$ sont orthogonaux, c'est-à-dire que le triangle $MAB$ est rectangle en $M$ (ou que $M=A$ ou $M=B$) : l'ensemble cherché est le cercle de diamètre $[AB]$.", 'Étape 2 : Le centre est le milieu de $[AB]$ : $\\Omega\\left(\\dfrac{2+-4}{2};\\dfrac{5+1}{2}\\right)=\\Omega(-1;3)$.', 'Étape 3 : $AB^2=(-4-(2))^2+(1-(5))^2=52$, donc le rayon est $r=\\dfrac{AB}{2}=\\sqrt{\\dfrac{AB^2}{4}}=\\sqrt{13}=\\sqrt{13}$.')),
    (2185, "Étude d'un ensemble de points", 2, "On donne les points $A(-3 ; -2)$ et $B(3 ; 6)$. Déterminer l'ensemble des points $M$ du plan tels que $\\vec{MA} \\cdot \\vec{MB} = 0$.", 'Le cercle de diamètre $[AB]$, de centre $\\Omega\\left(0 ; 2\\right)$ et de rayon $5$', '$\\vec{MA}\\cdot\\vec{MB}=0$ signifie que $M$ voit $[AB]$ sous un angle droit.', ("Étape 1 : $\\vec{MA}\\cdot\\vec{MB}=0$ signifie que $\\vec{MA}$ et $\\vec{MB}$ sont orthogonaux, c'est-à-dire que le triangle $MAB$ est rectangle en $M$ (ou que $M=A$ ou $M=B$) : l'ensemble cherché est le cercle de diamètre $[AB]$.", 'Étape 2 : Le centre est le milieu de $[AB]$ : $\\Omega\\left(\\dfrac{-3+3}{2};\\dfrac{-2+6}{2}\\right)=\\Omega(0;2)$.', 'Étape 3 : $AB^2=(3-(-3))^2+(6-(-2))^2=100$, donc le rayon est $r=\\dfrac{AB}{2}=\\sqrt{\\dfrac{AB^2}{4}}=\\sqrt{25}=5$.')),
    (2186, "Étude d'un ensemble de points", 3, "On donne les points $A(0 ; 0)$ et $B(8 ; -6)$. Déterminer l'ensemble des points $M$ du plan tels que $\\vec{MA} \\cdot \\vec{MB} = 0$.", 'Le cercle de diamètre $[AB]$, de centre $\\Omega\\left(4 ; -3\\right)$ et de rayon $5$', '$\\vec{MA}\\cdot\\vec{MB}=0$ signifie que $M$ voit $[AB]$ sous un angle droit.', ("Étape 1 : $\\vec{MA}\\cdot\\vec{MB}=0$ signifie que $\\vec{MA}$ et $\\vec{MB}$ sont orthogonaux, c'est-à-dire que le triangle $MAB$ est rectangle en $M$ (ou que $M=A$ ou $M=B$) : l'ensemble cherché est le cercle de diamètre $[AB]$.", 'Étape 2 : Le centre est le milieu de $[AB]$ : $\\Omega\\left(\\dfrac{0+8}{2};\\dfrac{0+-6}{2}\\right)=\\Omega(4;-3)$.', 'Étape 3 : $AB^2=(8-(0))^2+(-6-(0))^2=100$, donc le rayon est $r=\\dfrac{AB}{2}=\\sqrt{\\dfrac{AB^2}{4}}=\\sqrt{25}=5$.')),
    (2187, "Étude d'un ensemble de points", 3, "On donne le point $A(1 ; 2)$, le vecteur $\\vec{u}(3 ; -2)$ et le point $N(4 ; 1)$. Caractériser géométriquement l'ensemble $\\mathcal{E}$ des points $M$ tels que $\\vec{AM}\\cdot\\vec{u}=0$, puis déterminer si $N(4 ; 1)$ appartient à $\\mathcal{E}$.", "$\\mathcal{E}$ est la droite d'équation $3x -2y +1 = 0$ ; $N$ n'appartient pas à $\\mathcal{E}$", "$\\mathcal{E}$ est la droite passant par $A$ de vecteur normal $\\vec{u}$ ; vérifier ensuite si les coordonnées de $N$ vérifient l'équation obtenue.", ("Étape 1 : $\\mathcal{E}$ est la droite passant par $A$ de vecteur normal $\\vec{u}$, d'équation $3x -2y +1 = 0$.", 'Étape 2 : On remplace $x$ et $y$ par les coordonnées de $N$ : $(3)\\times(4)+(-2)\\times(1)+1 = 11$.', "Étape 3 : On obtient $11 \\neq 0$ : $N$ ne vérifie pas l'équation de $\\mathcal{E}$, donc $N \\notin \\mathcal{E}$.")),
    (2188, "Étude d'un ensemble de points", 3, "On donne le point $A(-2 ; 0)$, le vecteur $\\vec{u}(5 ; 1)$ et le point $N(-1 ; -5)$. Caractériser géométriquement l'ensemble $\\mathcal{E}$ des points $M$ tels que $\\vec{AM}\\cdot\\vec{u}=0$, puis déterminer si $N(-1 ; -5)$ appartient à $\\mathcal{E}$.", "$\\mathcal{E}$ est la droite d'équation $5x +1y +10 = 0$ ; $N$ appartient à $\\mathcal{E}$", "$\\mathcal{E}$ est la droite passant par $A$ de vecteur normal $\\vec{u}$ ; vérifier ensuite si les coordonnées de $N$ vérifient l'équation obtenue.", ("Étape 1 : $\\mathcal{E}$ est la droite passant par $A$ de vecteur normal $\\vec{u}$, d'équation $5x +1y +10 = 0$.", 'Étape 2 : On remplace $x$ et $y$ par les coordonnées de $N$ : $(5)\\times(-1)+(1)\\times(-5)+10 = 0$.', "Étape 3 : On obtient $0$ : $N$ vérifie l'équation de $\\mathcal{E}$, donc $N \\in \\mathcal{E}$.")),
    (2189, "Étude d'un ensemble de points", 3, "On donne le point $A(2 ; q)$ et le vecteur $\\vec{u}(3 ; -1)$. L'ensemble des points $M(x;y)$ tels que $\\vec{AM}\\cdot\\vec{u}=0$ a pour équation $3x -1y -2 = 0$. Déterminer $q$.", '$q = 4$', "Le terme constant de l'équation obtenue vaut $-(u_x\\,x_A+u_y\\,q)$ : l'identifier au terme constant donné.", ("Étape 1 : L'équation de la droite $\\vec{AM}\\cdot\\vec{u}=0$ est $3(x-(2))+-1(y-q)=0$, soit $3x -1y-(3\\times2+-1\\times q)=0$.", "Étape 2 : En identifiant le terme constant : $-(6+-1q) = -2$, donc $-1q = -4$, d'où $q = 4$.")),
    (2190, "Étude d'un ensemble de points", 3, "On donne le point $A(-3 ; q)$ et le vecteur $\\vec{u}(4 ; 5)$. L'ensemble des points $M(x;y)$ tels que $\\vec{AM}\\cdot\\vec{u}=0$ a pour équation $4x +5y +22 = 0$. Déterminer $q$.", '$q = -2$', "Le terme constant de l'équation obtenue vaut $-(u_x\\,x_A+u_y\\,q)$ : l'identifier au terme constant donné.", ("Étape 1 : L'équation de la droite $\\vec{AM}\\cdot\\vec{u}=0$ est $4(x-(-3))+5(y-q)=0$, soit $4x +5y-(4\\times-3+5\\times q)=0$.", "Étape 2 : En identifiant le terme constant : $-(-12+5q) = 22$, donc $5q = -10$, d'où $q = -2$.")),
    (2191, "Étude d'un ensemble de points", 3, "Vrai ou faux ? On donne $A(1 ; -2)$ et $\\vec{u}(3 ; 4)$. Soit $\\mathcal{E}$ l'ensemble des points $M$ tels que $\\vec{AM}\\cdot\\vec{u}=0$. Le point $N(5 ; -1)$ appartient à $\\mathcal{E}$. Justifier.", 'Faux', 'Calculer $\\vec{AN}\\cdot\\vec{u}$ : $N$ appartient à $\\mathcal{E}$ si, et seulement si, ce produit scalaire est nul.', ('Étape 1 : $\\vec{AN}(5-1 ; -1-(-2)) = \\vec{AN}(4 ; 1)$.', 'Étape 2 : $\\vec{AN}\\cdot\\vec{u} = 4\\times3+1\\times4 = 16$.', "Étape 3 : Le produit scalaire n'est pas nul : $N$ n'appartient donc pas à $\\mathcal{E}$. L'affirmation est fausse.")),
    (2192, "Étude d'un ensemble de points", 3, "Vrai ou faux ? On donne $A(-2 ; 3)$ et $\\vec{u}(1 ; 2)$. Soit $\\mathcal{E}$ l'ensemble des points $M$ tels que $\\vec{AM}\\cdot\\vec{u}=0$. Le point $N(0 ; 2)$ appartient à $\\mathcal{E}$. Justifier.", 'Vrai', 'Calculer $\\vec{AN}\\cdot\\vec{u}$ : $N$ appartient à $\\mathcal{E}$ si, et seulement si, ce produit scalaire est nul.', ('Étape 1 : $\\vec{AN}(0-(-2) ; 2-3) = \\vec{AN}(2 ; -1)$.', 'Étape 2 : $\\vec{AN}\\cdot\\vec{u} = 2\\times1+(-1)\\times2 = 2-2 = 0$.', "Étape 3 : Le produit scalaire est nul : $N$ appartient donc bien à $\\mathcal{E}$. L'affirmation est vraie.")),
    (2193, "Étude d'un ensemble de points", 3, "On donne $A(2 ; -1)$ et $\\vec{u}(3 ; 5)$. Un élève affirme : « l'ensemble des points $M$ tels que $\\vec{AM}\\cdot\\vec{u}=0$ est la droite passant par $A$ et **parallèle** à $\\vec{u}$ ». Identifier et corriger son erreur.", "C'est la droite passant par $A$ et de vecteur normal $\\vec{u}$ (donc perpendiculaire à $\\vec{u}$), pas parallèle", '$\\vec{AM}\\cdot\\vec{u}=0$ signifie que $\\vec{AM}$ et $\\vec{u}$ sont orthogonaux, pas colinéaires.', ('Étape 1 : $\\vec{AM}\\cdot\\vec{u}=0$ signifie que $\\vec{AM}$ et $\\vec{u}$ sont orthogonaux : $\\vec{u}$ est donc un vecteur normal à la droite, pas un vecteur directeur.', "Étape 2 : L'élève a confondu orthogonalité et colinéarité : la droite cherchée est bien celle passant par $A$, mais de vecteur **normal** $\\vec{u}$ (donc perpendiculaire à la direction de $\\vec{u}$), et non parallèle à $\\vec{u}$.", 'Étape 3 : Une équation correcte de cette droite est $3(x-2)+5(y+1)=0$, soit $3x+5y-1=0$.')),
    (2194, "Étude d'un ensemble de points", 3, "On donne $A(0 ; 3)$ et $B(6 ; -1)$. Un élève affirme : « l'ensemble des points $M$ tels que $\\vec{MA}\\cdot\\vec{MB}=0$ est le cercle de centre $A$ et de rayon $AB$ ». Identifier et corriger son erreur.", "C'est le cercle de diamètre $[AB]$, de centre le milieu de $[AB]$, pas de centre $A$", '$\\vec{MA}\\cdot\\vec{MB}=0$ caractérise le cercle de diamètre $[AB]$, pas un cercle centré en $A$.', ("Étape 1 : L'ensemble des points $M$ tels que $\\vec{MA}\\cdot\\vec{MB}=0$ est le cercle de diamètre $[AB]$ (car $M$ voit alors $[AB]$ sous un angle droit), et non un cercle centré en $A$.", 'Étape 2 : Le centre correct est le milieu de $[AB]$ : $\\Omega(3;1)$, et le rayon correct est $\\dfrac{AB}{2}$, pas $AB$.', 'Étape 3 : $AB^2 = 6^2+(-4)^2=52$, donc le rayon correct est $r=\\dfrac{\\sqrt{52}}{2}=\\sqrt{13}$, et non $AB=\\sqrt{52}=2\\sqrt{13}$.')),
    (2195, "Étude d'un ensemble de points", 4, "Soit $A(x_A;y_A)$ un point et $\\vec{u}(a;b)$ un vecteur non nul du plan. Démontrer que l'ensemble $\\mathcal{E}$ des points $M(x;y)$ tels que $\\vec{AM}\\cdot\\vec{u}=0$ est une droite, dont on donnera une équation.", "$\\mathcal{E}$ est la droite d'équation $a(x-x_A)+b(y-y_A)=0$, soit $ax+by-(ax_A+by_A)=0$", 'Exprimer $\\vec{AM}$ en fonction de $x,y,x_A,y_A$, puis développer le produit scalaire $\\vec{AM}\\cdot\\vec{u}$.', ('Étape 1 : $\\vec{AM}(x-x_A ; y-y_A)$, donc $\\vec{AM}\\cdot\\vec{u} = a(x-x_A)+b(y-y_A)$.', "Étape 2 : La condition $\\vec{AM}\\cdot\\vec{u}=0$ s'écrit donc $a(x-x_A)+b(y-y_A)=0$, soit en développant $ax+by-(ax_A+by_A)=0$.", "Étape 3 : C'est une équation de la forme $\\alpha x+\\beta y+\\gamma=0$ avec $(\\alpha;\\beta)=(a;b)\\neq(0;0)$ : c'est bien l'équation d'une droite (celle passant par $A$ et de vecteur normal $\\vec{u}$).")),
    (2196, "Étude d'un ensemble de points", 5, "Soit $A(x_A;y_A)$ et $B(x_B;y_B)$ deux points distincts du plan. Démontrer que l'ensemble des points $M$ tels que $\\vec{MA}\\cdot\\vec{MB}=0$ est le cercle de diamètre $[AB]$.", "C'est le cercle de centre $\\Omega$, milieu de $[AB]$, et de rayon $\\dfrac{AB}{2}$", 'Introduire le milieu $\\Omega$ de $[AB]$ et écrire $\\vec{MA}=\\vec{M\\Omega}+\\vec{\\Omega A}$, $\\vec{MB}=\\vec{M\\Omega}+\\vec{\\Omega B}$, en utilisant $\\vec{\\Omega A}=-\\vec{\\Omega B}$.', ('Étape 1 : Soit $\\Omega$ le milieu de $[AB]$. On a $\\vec{MA}=\\vec{M\\Omega}+\\vec{\\Omega A}$ et $\\vec{MB}=\\vec{M\\Omega}+\\vec{\\Omega B}=\\vec{M\\Omega}-\\vec{\\Omega A}$ (car $\\vec{\\Omega B}=-\\vec{\\Omega A}$).', 'Étape 2 : $\\vec{MA}\\cdot\\vec{MB} = \\left(\\vec{M\\Omega}+\\vec{\\Omega A}\\right)\\cdot\\left(\\vec{M\\Omega}-\\vec{\\Omega A}\\right) = \\|\\vec{M\\Omega}\\|^2-\\|\\vec{\\Omega A}\\|^2$.', "Étape 3 : La condition $\\vec{MA}\\cdot\\vec{MB}=0$ équivaut donc à $\\|\\vec{M\\Omega}\\|^2=\\|\\vec{\\Omega A}\\|^2$, c'est-à-dire $M\\Omega = \\Omega A = \\dfrac{AB}{2}$ : $M$ décrit exactement le cercle de centre $\\Omega$ et de rayon $\\dfrac{AB}{2}$, c'est-à-dire le cercle de diamètre $[AB]$.")),
    (2197, "Étude d'un ensemble de points", 2, "Deux caméras de surveillance sont installées aux points $A(0 ; 0)$ et $B(10 ; 0)$ (coordonnées en mètres). On admet qu'une personne située en un point $M$ est vue sous un angle droit par les deux caméras (c'est-à-dire que $\\vec{MA}\\cdot\\vec{MB}=0$) exactement lorsqu'elle se trouve sur une certaine courbe $\\mathcal{E}$. Caractériser $\\mathcal{E}$.", '$\\mathcal{E}$ est le cercle de diamètre $[AB]$, de centre $\\Omega(5;0)$ et de rayon $5$', '$\\vec{MA}\\cdot\\vec{MB}=0$ caractérise le cercle de diamètre $[AB]$.', ("Étape 1 : L'ensemble $\\mathcal{E}$ est le cercle de diamètre $[AB]$.", 'Étape 2 : Le centre est le milieu de $[AB]$ : $\\Omega(5;0)$, et $AB=10$, donc le rayon est $r=5$.')),
    (2198, "Étude d'un ensemble de points", 2, "Un phare situé au point $A(1 ; 2)$ (coordonnées en kilomètres) éclaire selon un faisceau perpendiculaire à la direction $\\vec{u}(2 ; -3)$. On admet qu'un bateau est éclairé exactement lorsqu'il se trouve sur la droite $\\mathcal{E}$ des points $M$ tels que $\\vec{AM}\\cdot\\vec{u}=0$. Donner une équation de $\\mathcal{E}$.", '$\\mathcal{E} : 2x -3y +4 = 0$', '$\\mathcal{E}$ est la droite passant par $A$ de vecteur normal $\\vec{u}$.', ('Étape 1 : Une équation de $\\mathcal{E}$ est $2(x-1)-3(y-2)=0$.', 'Étape 2 : En développant : $2x-2-3y+6=0$, soit $2x-3y+4=0$.')),
    (2199, "Étude d'un ensemble de points", 4, "On donne $A(-2 ; 1)$ et $B(4 ; 5)$. Pour caractériser l'ensemble $\\mathcal{E}$ des points $M$ tels que $\\vec{MA}\\cdot\\vec{MB}=0$, un élève utilise directement la propriété du cours (cercle de diamètre $[AB]$) ; un autre développe $\\vec{MA}\\cdot\\vec{MB}=0$ en coordonnées pour obtenir une équation, puis la met sous forme canonique. Mener les deux méthodes et vérifier qu'elles donnent le même résultat.", 'Les deux méthodes donnent le cercle de centre $\\Omega(1;3)$ et de rayon $\\sqrt{13}$', 'La méthode par coordonnées doit, après complétion du carré, redonner le centre (milieu de $[AB]$) et le rayon ($AB/2$) trouvés par la méthode directe.', ('Étape 1 (méthode directe) : $\\mathcal{E}$ est le cercle de diamètre $[AB]$, de centre $\\Omega\\left(\\dfrac{-2+4}{2};\\dfrac{1+5}{2}\\right)=\\Omega(1;3)$ et de rayon $r=\\dfrac{AB}{2}$ avec $AB^2=6^2+4^2=52$, donc $r=\\sqrt{13}$.', 'Étape 2 (méthode par coordonnées) : $\\vec{MA}(-2-x;1-y)$ et $\\vec{MB}(4-x;5-y)$, donc $\\vec{MA}\\cdot\\vec{MB} = (-2-x)(4-x)+(1-y)(5-y) = x^2-2x-8+y^2-6y+5 = x^2+y^2-2x-6y-3$.', "Étape 3 : L'équation $x^2+y^2-2x-6y-3=0$ se met sous forme canonique $(x-1)^2+(y-3)^2 = 1+9+3 = 13$, soit centre $\\Omega(1;3)$ et rayon $\\sqrt{13}$ : les deux méthodes concordent bien.")),
)
